// Validates /tmp/room-long/new-lines.jsonl (or the merged room.jsonl when given a path).
import fs from "node:fs";

const target = process.argv[2] ?? "/tmp/room-long/new-lines.jsonl";
const lines = fs.readFileSync(target, "utf8").split("\n").filter(Boolean);
let failures = 0;
const fail = (msg) => {
  failures++;
  console.log("  FAIL:", msg);
};

const KINDS = new Set([
  "unsupported-claim", "factual-error", "weak-argument", "strong-passage",
  "bloat", "repetition", "audience-gap", "buried-lede",
]);
const EDITORS = ["devil", "angel", "scholar", "editor", "reader"];

const cases = [];
for (const [i, line] of lines.entries()) {
  try {
    cases.push(JSON.parse(line));
  } catch (e) {
    fail(`line ${i + 1} does not parse: ${e.message}`);
  }
}
console.log(`${target}: ${lines.length} lines, ${cases.length} parsed`);

if (target.endsWith("room.jsonl")) {
  const orig = fs.readFileSync("/tmp/room.orig.jsonl", "utf8");
  const merged = fs.readFileSync(target, "utf8");
  if (merged.startsWith(orig)) console.log("  original 8 lines unchanged (byte-for-byte prefix)");
  else fail("merged file does not start with the original bytes");
  if (lines.length !== 10) fail(`expected 10 lines, got ${lines.length}`);
}

for (const c of cases) {
  if (!c.case_id.startsWith("room-long-")) continue;
  console.log(`\n== ${c.case_id} (${c.genre})`);
  const d = c.draftText;
  const len = d.length;
  const words = d.trim().split(/\s+/).length;
  console.log(`  words=${words} chars=${len} plants=${c.plants.length}`);
  if (words < 2200 || words > 3000) fail(`word count ${words} outside 2200..3000`);
  if (len <= 4500) fail(`draft is ${len} chars; must exceed the 4500 clamp`);
  if (c.plants.length < 7 || c.plants.length > 8) fail(`${c.plants.length} plants; need 7 or 8`);
  if (/[^\x20-\x7e\n]/.test(d)) fail("draft has non-ASCII characters");
  for (const k of ["case_id", "genre", "brief", "draftText", "plants"]) if (!(k in c)) fail(`missing key ${k}`);

  const regions = { head: 0, middle: 0, tail: 0, other: 0 };
  const kinds = new Set();
  const editors = new Set();
  const ids = new Set();
  let middleStrong = false;

  for (const p of c.plants) {
    if (ids.has(p.id)) fail(`duplicate plant id ${p.id}`);
    ids.add(p.id);
    if (!KINDS.has(p.kind)) fail(`${p.id}: unknown kind ${p.kind}`);
    kinds.add(p.kind);
    for (const e of p.expectedEditors) {
      if (!EDITORS.includes(e)) fail(`${p.id}: unknown editor ${e}`);
      editors.add(e);
    }
    const pw = p.passage.trim().split(/\s+/).length;
    if (pw < 8 || pw > 40) fail(`${p.id}: passage is ${pw} words (need 8..40)`);
    if (/[^\x20-\x7e]/.test(p.passage)) fail(`${p.id}: passage has non-ASCII characters`);
    const start = d.indexOf(p.passage);
    const end = start + p.passage.length;
    const count = start < 0 ? 0 : d.split(p.passage).length - 1;
    if (count !== 1) fail(`${p.id}: passage occurs ${count} times (need exactly 1)`);
    let region = "other";
    if (start >= 0 && end <= 3000) region = "head";
    else if (start > 3300 && end < len - 1500) region = "middle";
    else if (start >= len - 1300) region = "tail";
    regions[region]++;
    if (region === "middle" && p.kind === "strong-passage") middleStrong = true;
    console.log(
      `  ${p.id.padEnd(3)} ${p.kind.padEnd(17)} start=${String(start).padStart(5)} end=${String(end).padStart(5)} ${region}  [${p.expectedEditors.join(",")}]`,
    );
  }
  console.log(`  regions: head=${regions.head} middle=${regions.middle} tail=${regions.tail} other=${regions.other}`);
  if (regions.head < 2) fail("fewer than 2 head plants");
  if (regions.middle < 3) fail("fewer than 3 middle plants");
  if (regions.tail < 1) fail("no tail plant");
  if (!middleStrong) fail("no strong-passage in the middle region");
  const missingEditors = EDITORS.filter((e) => !editors.has(e));
  if (missingEditors.length) fail(`editors never targeted: ${missingEditors.join(",")}`);
  console.log(`  kinds: ${[...kinds].sort().join(", ")}`);
  console.log(`  editors: ${[...editors].sort().join(", ")}`);
}

console.log(failures ? `\n${failures} failure(s)` : "\nALL CHECKS PASSED");
process.exit(failures ? 1 : 0);

